function initCandlestickCharts(){if(!window.echarts)return;document.querySelectorAll(".candlestick-module").forEach(e=>{if(e.dataset.initialized==="true")return;const s=e.querySelector(".candlestick-chart"),o=e.querySelector('script[type="application/json"]');if(!s||!o)return;const t=JSON.parse(o.textContent),n=typeof t=="string"?JSON.parse(t):t;if(!Array.isArray(n))return;const i=window.echarts.init(s),a=n.map(e=>[e[1],e[4],e[3],e[2]]);i.setOption({backgroundColor:"transparent",grid:{left:58,right:20,top:18,bottom:42},tooltip:{trigger:"axis"},xAxis:{type:"category",data:n.map(e=>e[0]),axisLabel:{color:"#8998a9"},axisLine:{lineStyle:{color:"#1d3041"}}},yAxis:{type:"value",axisLabel:{color:"#8998a9"},splitLine:{lineStyle:{color:"#1d3041"}}},series:[{type:"candlestick",data:a,itemStyle:{color:"#00f5d4",color0:"#ff6b6b",borderColor:"#00f5d4",borderColor0:"#ff6b6b"}}]}),window.addEventListener("resize",()=>i.resize()),e.dataset.initialized="true"})}window.DualityModules=window.DualityModules||{},window.DualityModules.initCandlestickCharts=initCandlestickCharts